25	    expect(graph.getChildren(group.id)).toEqual([child.id]);
26	    expect(graph.getParent(child.id)).toBe(group.id);
27	    expect(registry.get(group.id)).toBe(group);
28	  });
29	
30	  it("addLayer rejects a parent that is not a Group layer", () => {
31	    const { graph } = setup();
32	    const leaf = createShapeLayer({ id: createLayerId("leaf"), name: "Box" });
33	    graph.addLayer(leaf);
34	    const child = createShapeLayer({
35	      id: createLayerId("child"),
36	      name: "Circle",
37	      parentId: leaf.id,
38	    });
39	    expect(() => graph.addLayer(child)).toThrow(/not a Group layer/);
40	  });
